def stride_coord_to_file_coord(x, y, w, h):
    x -= 7
    y -= 7
    if x < 0 or y < 0:
        return -1
    if y >= h:
        raise RuntimeError("too smol")
    if x >= w:
        return -2
    return (y*w+x)*2

